export const getStateBySlug = (slug) => {
  if (!slug) return null;
  const s = String(slug).toLowerCase().trim();
  return INDIA_STATES.find(state => 
    state.slug === s || 
    state.code.toLowerCase() === s || 
    state.id.toLowerCase() === s ||
    state.name.toLowerCase() === s
  ) || null;
};

export const getStateById = (id) => {
  if (!id) return null;
  return INDIA_STATES.find(state => state.id === id || state.code === id) || null;
};

export default INDIA_STATES;
